type GenerationCapacityReason =
  'process_arguments' | 'request_size' | 'model_context';

const CAPACITY_CONSTRAINTS: Record<GenerationCapacityReason, string> = {
  process_arguments: 'The worker process rejected its input arguments (E2BIG).',
  request_size: 'The provider rejected the request size.',
  model_context:
    'The model rejected the request because its input or context limit was exceeded.',
};

const CONTEXT_CAPACITY_CODES = new Set([
  'context_length_exceeded',
  'context_window_exceeded',
  'prompt_too_long',
  'input_tokens_exceeded',
  'input_token_limit_exceeded',
]);

const CONTEXT_CAPACITY_MESSAGE =
  /\b(?:prompt|input) (?:is )?too long\b|\bmaximum context length\b|\bexceeds? (?:the )?context (?:window|length)\b|\bcontext (?:length|window) (?:has been |is )?exceeded\b|\binput token(?:s| limit)? (?:has been |is )?exceeded\b/i;

export class GenerationCapacityError extends Error {
  readonly code = 'GENERATION_CAPACITY_EXCEEDED';

  constructor(
    readonly reason: GenerationCapacityReason,
    status?: 413,
  ) {
    const constraint =
      status === 413
        ? 'The provider rejected the request size (HTTP 413).'
        : CAPACITY_CONSTRAINTS[reason];
    super(
      `${constraint} ` +
        'Saved documents are unchanged. Run `rivet context list` and choose ' +
        'document IDs with `--exclude-guidance`, use `--guidance off` ' +
        'for this request, or reduce other request content before retrying.',
    );
    this.name = 'GenerationCapacityError';
  }
}

export const getGenerationCapacityError = (
  failure: unknown,
): GenerationCapacityError | undefined => {
  if (failure instanceof GenerationCapacityError) return failure;
  if (typeof failure === 'string') {
    if (
      /\brate.?limit\b|\btokens? per (?:minute|second)\b|Gateway request failed \(429\)/i.test(
        failure,
      )
    )
      return undefined;
    if (/Gateway request failed \(413\)/i.test(failure))
      return new GenerationCapacityError('request_size', 413);
    return CONTEXT_CAPACITY_MESSAGE.test(failure)
      ? new GenerationCapacityError('model_context')
      : undefined;
  }
  if (!failure || typeof failure !== 'object') return undefined;
  const error = failure as Record<string, unknown>;
  const code =
    typeof error.code === 'string' ? error.code.toLowerCase() : undefined;
  if (code === 'e2big') return new GenerationCapacityError('process_arguments');
  if (
    error.status === 413 ||
    error.statusCode === 413 ||
    error.api_error_status === 413
  )
    return new GenerationCapacityError('request_size', 413);
  if (code === 'request_too_large')
    return new GenerationCapacityError('request_size');
  if (code && CONTEXT_CAPACITY_CODES.has(code))
    return new GenerationCapacityError('model_context');
  if (
    error.status === 429 ||
    error.statusCode === 429 ||
    error.api_error_status === 429
  )
    return undefined;
  return (
    getGenerationCapacityError(error.message) ??
    getGenerationCapacityError(error.result) ??
    (error.error !== failure
      ? getGenerationCapacityError(error.error)
      : undefined)
  );
};
